import asyncio
from typing import Optional
from redis.asyncio import Redis
from contextlib import asynccontextmanager
import time
import uuid

from app.core.logging import get_logger
from app.core.metrics import lock_contention_counter, lock_acquisition_histogram
from app.config import settings

logger = get_logger(__name__)


class DistributedLock:
    def __init__(self, redis_client: Redis):
        self.redis = redis_client
        self.lock_timeout = settings.LOCK_TIMEOUT_MS
        self.retry_delay = settings.LOCK_RETRY_DELAY_MS
        self.max_retries = settings.LOCK_MAX_RETRIES

    @asynccontextmanager
    async def acquire(self, resource: str, owner: Optional[str] = None):
        """
        Distributed lock with automatic release
        """
        if owner is None:
            owner = str(uuid.uuid4())

        lock_key = f"lock:{resource}"
        acquired = False
        start_time = time.time()

        try:
            # Try to acquire lock with retries
            for attempt in range(self.max_retries):
                acquired = await self._try_acquire(lock_key, owner)

                if acquired:
                    acquisition_time = (time.time() - start_time) * 1000
                    lock_acquisition_histogram.observe(acquisition_time)
                    logger.info(
                        "Lock acquired",
                        extra={
                            "lock_key": lock_key,
                            "owner": owner,
                            "attempt": attempt + 1,
                            "acquisition_time_ms": acquisition_time
                        }
                    )
                    break

                if attempt < self.max_retries - 1:
                    await asyncio.sleep(self.retry_delay / 1000)
                    lock_contention_counter.inc()

            if not acquired:
                raise LockAcquisitionError(f"Failed to acquire lock for {resource}")

            yield owner

        finally:
            if acquired:
                await self._release(lock_key, owner)
                logger.debug("Lock released", extra={"lock_key": lock_key, "owner": owner})

    async def _try_acquire(self, lock_key: str, owner: str) -> bool:
        """
        Try to acquire lock using SET NX PX
        """
        result = await self.redis.set(
            lock_key,
            owner,
            px=self.lock_timeout,
            nx=True
        )
        return result is True

    async def _release(self, lock_key: str, owner: str) -> bool:
        """
        Release lock using Lua script to ensure atomicity
        """
        lua_script = """
        if redis.call("get", KEYS[1]) == ARGV[1] then
            return redis.call("del", KEYS[1])
        else
            return 0
        end
        """
        result = await self.redis.eval(lua_script, 1, lock_key, owner)
        return result == 1


class LockAcquisitionError(Exception):
    """Raised when lock cannot be acquired"""
    pass
